//! Exact backend policy, error category, lazy ownership and CPU settlement witnesses.
mod support;
include!("../src/stdlib/futures/runtime.rs");
mod tsrust_native_threads{include!("../src/stdlib/threads/runtime_core.rs");include!("../src/stdlib/threads/runtime_async.rs");}
include!("../src/stdlib/compression/runtime.rs");
use tsrust_native_compression::{buffer,Format,Direction,Failure};
fn need<T>(value:Result<T,tsrust_native_compression::Error>)->T{value.unwrap_or_else(|error|panic!("{}: {}",error.code,error.message))}
#[test]fn native_levels_corruption_boundaries_and_explicit_output_limits(){for format in[Format::Gzip,Format::Zlib,Format::Raw]{for level in[None,Some(0),Some(1),Some(9)]{for size in[0,1,8191,8192,8193,32768]{let bytes=(0..size).map(|i|((i*17+5)%251)as u8).collect::<Vec<_>>();let encoded=need(buffer(bytes.clone(),format,Direction::Encode,level,"encode"));assert_eq!(need(buffer(encoded.clone(),format,Direction::Decode,None,"decode")),bytes);assert_eq!(need(buffer(encoded.clone(),format,Direction::Decode,Some(size),"decode")),bytes);if size>0{assert!(matches!(buffer(encoded.clone(),format,Direction::Decode,Some(size-1),"decode"),Err(error)if error.code=="output-limit"));}assert!(buffer(encoded[..encoded.len()-1].to_vec(),format,Direction::Decode,None,"decode").is_err());assert!(buffer([encoded,b"trailing".to_vec()].concat(),format,Direction::Decode,None,"decode").is_err());}}}assert!(matches!(buffer(Vec::new(),Format::Gzip,Direction::Encode,Some(10),"gzip"),Err(error)if error.code=="range"));assert!(matches!(buffer(Vec::new(),Format::Gzip,Direction::Decode,Some(-1),"gunzip"),Err(error)if error.code=="range"));}
#[test]fn gzip_concatenation_crc_and_native_determinism(){let first=need(buffer(b"first".to_vec(),Format::Gzip,Direction::Encode,None,"gzip"));assert_eq!(first,need(buffer(b"first".to_vec(),Format::Gzip,Direction::Encode,None,"gzip")));let second=need(buffer(b"second".to_vec(),Format::Gzip,Direction::Encode,None,"gzip"));assert_eq!(need(buffer([first.clone(),second].concat(),Format::Gzip,Direction::Decode,None,"gunzip")),b"firstsecond");let mut corrupt=first;let crc=corrupt.len()-8;corrupt[crc]^=1;assert!(matches!(buffer(corrupt,Format::Gzip,Direction::Decode,None,"gunzip"),Err(error)if error.code=="codec"));}
#[test]fn lazy_closed_pool_failure_preserves_typed_admission(){tsrust_native_futures::block_on(async{let pool=tsrust_native_threads::create_pool(1,1).unwrap();let pending=tsrust_native_compression::run(pool.submission(),b"owned".to_vec(),Format::Gzip,Direction::Encode,None,"gzip");assert_eq!(pool.stats().outstanding,0);pool.shutdown().unwrap();assert!(matches!(pending.await,Err(Failure::Admission(error))if error.code=="closed"));});}
